        className: "language-typescript",
        children: "interface LearningSystemConfig {\n  goal: string\n  baselineScore: number\n  targetScore: number\n  deadline: Date\n  weeklyHours: number\n  subjects: SubjectPlan[]\n}\n\ninterface SubjectPlan {\n  name: string\n  baselineScore: number\n  weakTopics: string[]\n  dailyMinimum: number\n  phase: 'foundation' | 'practice' | 'mastery'\n}\n"
